package org.brightstats.data;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.brightstats.stats.*;
public final class LatentSettingsChecks {
    private static int checks;
    private static void check(boolean value){if(!value)throw new AssertionError("Latent settings check "+checks);checks++;}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid mapping accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Gson gson=new Gson();var polynomial=new NonlinearPls.Specification(List.of(new NonlinearPls.Extension(3,new int[]{1,2})),List.of(new PathProcess.Probe("A",Map.of(0,-1.0,1,.5))),new NonlinearPls.Grid(1,3,-2,2,7));JsonObject options=new JsonObject();options.add("specification",gson.toJsonTree(polynomial));options.add("bootstrap",gson.toJsonTree(new Bootstrap.Options(40,42,.95)));String before=options.toString();var remapped=LatentDiagramSettings.nonlinear(options,new int[]{-1,0,1,2});var value=NonlinearInput.specification(remapped.get("specification"));check(value.extensions().getFirst().target()==2);check(Arrays.equals(value.extensions().getFirst().factors(),new int[]{0,1}));check(value.probes().getFirst().values().equals(Map.of(0,.5)));check(value.grid().source()==0&&value.grid().target()==2);check(options.toString().equals(before));check(remapped.get("bootstrap").equals(options.get("bootstrap")));var lost=NonlinearInput.specification(LatentDiagramSettings.nonlinear(options,new int[]{0,-1,1,2}).get("specification"));check(lost.extensions().isEmpty()&&lost.grid()==null);check(LatentDiagramSettings.nonlinear(options,new int[]{-1,-1,-1,0})==null);reject(()->LatentDiagramSettings.nonlinear(options,new int[]{0,0,1,2}));reject(()->LatentDiagramSettings.nonlinear(options,new int[]{0,2,3,4}));
        var dimension=new HigherOrderPls.Dimension("H",new int[]{0,1,2},PlsSem.Mode.B,PlsSem.MeasurementType.FORMATIVE,new double[]{1,2,3});var specification=new HigherOrderPls.Specification(new int[]{3,4},List.of(dimension),List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(0,1)),PlsSem.Options.defaults());options.add("specification",gson.toJsonTree(specification));before=options.toString();var rebased=HigherOrderInput.specification(LatentDiagramSettings.higherOrder(options,new int[]{-1,0,1,2,3}).get("specification"));check(Arrays.equals(rebased.retained(),new int[]{2,3}));check(Arrays.equals(rebased.higherOrder().getFirst().lowerOrder(),new int[]{0,1}));check(Arrays.equals(rebased.higherOrder().getFirst().initialWeights(),new double[]{2,3}));check(rebased.edges().equals(specification.edges()));check(options.toString().equals(before));check(LatentDiagramSettings.higherOrder(options,new int[]{-1,-1,0,1,2})==null);
        var multiple=new HigherOrderPls.Specification(new int[]{4,5},List.of(new HigherOrderPls.Dimension("H1",new int[]{0,1},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null),new HigherOrderPls.Dimension("H2",new int[]{2,3},PlsSem.Mode.B,PlsSem.MeasurementType.FORMATIVE,null)),List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(3,0),new PlsSem.Edge(0,1),new PlsSem.Edge(3,1)),PlsSem.Options.defaults());options.add("specification",gson.toJsonTree(multiple));var reduced=HigherOrderInput.specification(LatentDiagramSettings.higherOrder(options,new int[]{0,-1,1,2,-1,3}).get("specification"));check(Arrays.equals(reduced.retained(),new int[]{3}));check(reduced.higherOrder().size()==1&&reduced.higherOrder().getFirst().name().equals("H2"));check(Arrays.equals(reduced.higherOrder().getFirst().lowerOrder(),new int[]{1,2}));check(reduced.edges().equals(List.of(new PlsSem.Edge(1,0))));Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("latent-settings-checks.json"),"{\"checks\":"+checks+"}");System.out.println("{\"checks\":"+checks+"}");}
}
